#!/bin/bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PKG="$(cd "$SCRIPT_DIR/.." && pwd)"
ROOT="$(cd "$PKG/.." && pwd)"
OUT="$ROOT/build/FanBar.app"
UID_VALUE="$(id -u)"

cat > "$PKG/Sources/FanBarHelper/GeneratedConfig.swift" <<EOF
// Regenerated by Scripts/build-app.sh with the installing user's UID.
import Darwin

enum GeneratedConfig {
    static let allowedUID: uid_t = $UID_VALUE
}
EOF

echo "Building FanBar (UID $UID_VALUE)..."
swift build -c release --package-path "$PKG"

rm -rf "$OUT"
mkdir -p "$OUT/Contents/MacOS" "$OUT/Contents/Resources"
cp "$PKG/.build/release/FanBarApp" "$OUT/Contents/MacOS/FanBar"
cp "$PKG/.build/release/FanBarHelper" "$OUT/Contents/MacOS/fanbar-helper"
cp "$PKG/Resources/Info.plist" "$OUT/Contents/Info.plist"
cp "$PKG/Scripts/install-helper-root.sh" "$OUT/Contents/Resources/install-helper-root.sh"
cp "$PKG/Scripts/uninstall-helper-root.sh" "$OUT/Contents/Resources/uninstall-helper-root.sh"
chmod 755 "$OUT/Contents/MacOS/FanBar" "$OUT/Contents/MacOS/fanbar-helper"
chmod 755 "$OUT/Contents/Resources/"*.sh

codesign --force --sign - --deep "$OUT"
xattr -dr com.apple.quarantine "$OUT" 2>/dev/null || true

# The app lives in /Applications so Login Items keeps a stable path.
if [ "${FANBAR_SKIP_INSTALL:-0}" != "1" ]; then
    rm -rf /Applications/FanBar.app
    cp -R "$OUT" /Applications/FanBar.app
    echo "Installed: /Applications/FanBar.app"
fi

echo "Built: $OUT"
